/// Generated high-level transition with typed state access, reasons, effects, and channels.
///
/// The private generic builder prevents raw path mutation, reason, effect, and outbox staging.
pub struct GeneratedTransition<'a, H: CommitmentHasher> {
    inner: CataloguedTransitionBuilder<'a, H>,
}

impl<'a, H: CommitmentHasher> GeneratedTransition<'a, H> {
    /// Reads root field `available` and records its exact read footprint.
    pub fn read_available(
        &mut self,
    ) -> Result<crate::oracle::templates::inventory_reservation::generated::Units, GeneratedProjectError> {
        let value = self
            .inner
            .read(crate::oracle::templates::inventory_reservation::generated::Stock::available_path())?
            .clone();
        Ok(crate::oracle::templates::inventory_reservation::generated::Units::try_from_value(value)?)
    }

    /// Reads root field `reserved` and records its exact read footprint.
    pub fn read_reserved(
        &mut self,
    ) -> Result<crate::oracle::templates::inventory_reservation::generated::Units, GeneratedProjectError> {
        let value = self
            .inner
            .read(crate::oracle::templates::inventory_reservation::generated::Stock::reserved_path())?
            .clone();
        Ok(crate::oracle::templates::inventory_reservation::generated::Units::try_from_value(value)?)
    }

    /// Stages a preconditioned update of root field `available`.
    pub fn update_available(
        &mut self,
        value: &crate::oracle::templates::inventory_reservation::generated::Units,
    ) -> Result<&mut Self, GeneratedProjectError> {
        self.inner.update(
            crate::oracle::templates::inventory_reservation::generated::Stock::available_path(),
            value.to_value()?,
        )?;
        Ok(self)
    }

    /// Stages a preconditioned update of root field `reserved`.
    pub fn update_reserved(
        &mut self,
        value: &crate::oracle::templates::inventory_reservation::generated::Units,
    ) -> Result<&mut Self, GeneratedProjectError> {
        self.inner.update(
            crate::oracle::templates::inventory_reservation::generated::Stock::reserved_path(),
            value.to_value()?,
        )?;
        Ok(self)
    }

    /// Records observation of context field `authorized`.
    pub fn observe_context_authorized(
        &mut self,
    ) -> Result<&mut Self, GeneratedProjectError> {
        let path = AccessPath::try_new(
            CONTEXT_TYPE_ID,
            vec![PathAtom::Field(130)],
        )
        .map_err(TransitionError::from)?;
        self.inner.observe_context(path)?;
        Ok(self)
    }

    /// Stages catalog channel `shipment` with reviewed destination and payload types.
    pub fn enqueue_channel_300(
        &mut self,
        ordinal: u32,
        destination: &crate::oracle::templates::inventory_reservation::generated::WarehouseDestination,
        payload: &crate::oracle::templates::inventory_reservation::generated::ShipmentRequest,
    ) -> Result<&mut Self, GeneratedProjectError> {
        let entry = channel_300(ordinal, destination, payload)?;
        self.inner.enqueue(entry)?;
        Ok(self)
    }

    /// Records an ordinary rejection when `condition` is false.
    pub fn require(&mut self, condition: bool, reason: RejectReasonId) -> Result<&mut Self, GeneratedProjectError> {
        self.inner.require(condition, reason.try_semantic_id()?)?;
        Ok(self)
    }

    /// Records a committed failure when `condition` is true.
    pub fn fail_if(&mut self, condition: bool, reason: CommittedFailureReasonId) -> Result<&mut Self, GeneratedProjectError> {
        self.inner.fail_if(condition, reason.try_semantic_id()?)?;
        Ok(self)
    }

    /// Canonicalizes, validates, resource-binds, and seals one decision.
    pub fn seal(self) -> Result<TransitionDecision, GeneratedProjectError> {
        Ok(self.inner.seal()?)
    }
}

/// Local generated-binding construction or admission failure.
///
/// This diagnostic order is not application rejection precedence.
#[derive(Clone, Debug, Eq, PartialEq)]
pub enum GeneratedProjectError {
    HashAlgorithmMismatch,
    SchemaHashMismatch { expected: Hash32, actual: Hash32 },
    ProfileHashMismatch { expected: Hash32, actual: Hash32 },
    CatalogHashMismatch { expected: Hash32, actual: Hash32 },
    RootTypeMismatch { expected: u32, actual: u32 },
    InputSchemaHashMismatch { kind: GeneratedInputKind, expected: Hash32, actual: Hash32 },
    InputTypeMismatch { kind: GeneratedInputKind, expected: u32, actual: u32 },
    InputCommitmentMismatch { kind: GeneratedInputKind, expected: Hash32, actual: Hash32 },
    ZeroInputCommitment(GeneratedInputKind),
    Catalog(CatalogError),
    Adapter(crate::oracle::templates::inventory_reservation::generated::AdapterError),
    Encode(EncodeError),
    Envelope(SchemaEnvelopeError),
    Profile(ProfileError),
    Schema(SchemaError),
    Transition(TransitionError),
}

impl From<CatalogError> for GeneratedProjectError {
    fn from(error: CatalogError) -> Self { Self::Catalog(error) }
}

impl From<crate::oracle::templates::inventory_reservation::generated::AdapterError> for GeneratedProjectError {
    fn from(error: crate::oracle::templates::inventory_reservation::generated::AdapterError) -> Self { Self::Adapter(error) }
}

impl From<EncodeError> for GeneratedProjectError {
    fn from(error: EncodeError) -> Self { Self::Encode(error) }
}

impl From<SchemaEnvelopeError> for GeneratedProjectError {
    fn from(error: SchemaEnvelopeError) -> Self { Self::Envelope(error) }
}

impl From<ProfileError> for GeneratedProjectError {
    fn from(error: ProfileError) -> Self { Self::Profile(error) }
}

impl From<SchemaError> for GeneratedProjectError {
    fn from(error: SchemaError) -> Self { Self::Schema(error) }
}

impl From<TransitionError> for GeneratedProjectError {
    fn from(error: TransitionError) -> Self { Self::Transition(error) }
}

impl fmt::Display for GeneratedProjectError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::HashAlgorithmMismatch => formatter.write_str("generated project hash algorithm mismatch"),
            Self::SchemaHashMismatch { expected, actual } => write!(formatter, "generated project schema hash mismatch: expected {expected}, actual {actual}"),
            Self::ProfileHashMismatch { expected, actual } => write!(formatter, "generated project profile hash mismatch: expected {expected}, actual {actual}"),
            Self::CatalogHashMismatch { expected, actual } => write!(formatter, "generated project catalog hash mismatch: expected {expected}, actual {actual}"),
            Self::RootTypeMismatch { expected, actual } => write!(formatter, "generated project root type mismatch: expected {expected}, actual {actual}"),
            Self::InputSchemaHashMismatch { kind, expected, actual } => write!(formatter, "generated {kind:?} schema hash mismatch: expected {expected}, actual {actual}"),
            Self::InputTypeMismatch { kind, expected, actual } => write!(formatter, "generated {kind:?} type mismatch: expected {expected}, actual {actual}"),
            Self::InputCommitmentMismatch { kind, expected, actual } => write!(formatter, "generated {kind:?} commitment mismatch: expected {expected}, actual {actual}"),
            Self::ZeroInputCommitment(kind) => write!(formatter, "generated {kind:?} commitment used the zero sentinel"),
            Self::Catalog(error) => write!(formatter, "generated catalog rejected: {error}"),
            Self::Adapter(error) => write!(formatter, "generated typed adapter rejected: {error:?}"),
            Self::Encode(error) => write!(formatter, "generated input commitment failed: {error}"),
            Self::Envelope(error) => write!(formatter, "generated schema envelope rejected: {error}"),
            Self::Profile(error) => write!(formatter, "generated profile rejected: {error}"),
            Self::Schema(error) => write!(formatter, "generated schema rejected: {error}"),
            Self::Transition(error) => write!(formatter, "generated transition rejected: {error}"),
        }
    }
}

